const REPORT_TYPE = "leak_detection";
const STATUSES = new Set(["draft", "submitted", "in_correction", "ready_to_send", "validated"]);
const SECTIONS = REPORT_STEP_KEYS;
const MAX_MEDIA_PER_REPORT = 40;
const MAX_MEDIA_SIZE = 4 * 1024 * 1024;
const MAX_REPORT_BYTES = 45 * 1024 * 1024;
const MAX_LIBRARY_ITEMS = 200;
const IMAGE_EXTENSIONS = new Set([".jpg", ".jpeg", ".png", ".webp"]);
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: MAX_MEDIA_SIZE, files: 5 }, fileFilter: (request, file, callback) => callback(null, IMAGE_EXTENSIONS.has(path.extname(file.originalname || "").toLowerCase())) });
const templateUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 2 * 1024 * 1024, files: 2 }, fileFilter: (request, file, callback) => callback(null, ["image/png", "image/jpeg", "image/webp"].includes(file.mimetype)) });

const defaultContent = () => createEmptyLeakContent();

export async function initializeTechnicalReports() {
    const database = getPool();
    await database.query(`
        CREATE TABLE IF NOT EXISTS depannhome_technical_reports (
            id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES depannhome_users(id) ON DELETE CASCADE,
            created_by BIGINT REFERENCES depannhome_users(id) ON DELETE SET NULL,
            appointment_id BIGINT REFERENCES depannhome_calendar_events(id) ON DELETE SET NULL,
            client_id VARCHAR(100) NOT NULL DEFAULT '', report_type VARCHAR(40) NOT NULL DEFAULT 'leak_detection',
            title VARCHAR(160) NOT NULL DEFAULT 'Rapport de recherche de fuite', report_date DATE NOT NULL DEFAULT CURRENT_DATE,
            content JSONB NOT NULL DEFAULT '{}'::jsonb, media JSONB NOT NULL DEFAULT '[]'::jsonb,
            status VARCHAR(30) NOT NULL DEFAULT 'draft', submitted_at TIMESTAMPTZ, validated_at TIMESTAMPTZ,
            validated_by BIGINT REFERENCES depannhome_users(id) ON DELETE SET NULL,
            proofread_at TIMESTAMPTZ, proofread_by BIGINT REFERENCES depannhome_users(id) ON DELETE SET NULL, proofread_fingerprint VARCHAR(64) NOT NULL DEFAULT '',
            pdf_data BYTEA, pdf_filename VARCHAR(255) NOT NULL DEFAULT '', document_mime_type VARCHAR(150) NOT NULL DEFAULT 'application/pdf',
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    `);
    await database.query(`ALTER TABLE depannhome_technical_reports ADD COLUMN IF NOT EXISTS proofread_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS proofread_by BIGINT REFERENCES depannhome_users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS proofread_fingerprint VARCHAR(64) NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS document_mime_type VARCHAR(150) NOT NULL DEFAULT 'application/pdf'`);
    await database.query("CREATE INDEX IF NOT EXISTS depannhome_technical_reports_owner_updated_idx ON depannhome_technical_reports (owner_id, updated_at DESC)");
    await database.query("CREATE INDEX IF NOT EXISTS depannhome_technical_reports_owner_appointment_idx ON depannhome_technical_reports (owner_id, appointment_id)");
    await database.query(`
        CREATE TABLE IF NOT EXISTS depannhome_technical_report_corrections (
            id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES depannhome_users(id) ON DELETE CASCADE,
            report_id BIGINT NOT NULL REFERENCES depannhome_technical_reports(id) ON DELETE CASCADE,
            section_key VARCHAR(40) NOT NULL, comment VARCHAR(2000) NOT NULL, requested_by BIGINT REFERENCES depannhome_users(id) ON DELETE SET NULL,
            resolved_at TIMESTAMPTZ, resolved_by BIGINT REFERENCES depannhome_users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    `);
    await database.query("CREATE INDEX IF NOT EXISTS depannhome_technical_report_corrections_report_idx ON depannhome_technical_report_corrections (owner_id, report_id, created_at DESC)");
    await database.query(`
        CREATE TABLE IF NOT EXISTS depannhome_technical_report_library (
            id BIGSERIAL PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES depannhome_users(id) ON DELETE CASCADE,
            category VARCHAR(40) NOT NULL, label VARCHAR(160) NOT NULL, content JSONB NOT NULL DEFAULT '{}'::jsonb,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    `);
    await database.query("CREATE INDEX IF NOT EXISTS depannhome_technical_report_library_owner_idx ON depannhome_technical_report_library (owner_id, category, LOWER(label))");
}

export function registerTechnicalReportRoutes(app, requireAuthentication) {
    app.use("/api/technical-reports", requireAuthentication, requireReportAccess);
    app.get("/api/technical-reports", asyncHandler(async (request, response) => { const ownerId = getAccountOwnerId(request); const library = await loadLibrary(ownerId); const materials = [...new Set([...DEFAULT_MATERIALS, ...library.filter(item => item.category === "materials").map(item => item.label)])]; response.json({ reports: await loadReports(ownerId, request), library, materials }); }));
    app.get("/api/technical-reports/template", requireReportAdministration, asyncHandler(async (request, response) => response.json({ template: await loadReportTemplate(getAccountOwnerId(request)) })));
    app.put("/api/technical-reports/template", requireReportAdministration, templateUpload.fields([{ name: "primaryLogo", maxCount: 1 }, { name: "secondaryLogo", maxCount: 1 }]), asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const template = sanitizeReportTemplate(request.body); const primaryLogo = request.files?.primaryLogo?.[0]; const secondaryLogo = request.files?.secondaryLogo?.[0]; const removePrimaryLogo = String(request.body?.removePrimaryLogo || "") === "true"; const removeSecondaryLogo = String(request.body?.removeSecondaryLogo || "") === "true";
        await getPool().query(`INSERT INTO depannhome_billing_profiles (owner_id, company_name, report_template, logo_data, logo_mime_type, report_secondary_logo_data, report_secondary_logo_mime_type) VALUES ($1,'',$2::jsonb,$3,$4,$5,$6) ON CONFLICT (owner_id) DO UPDATE SET report_template=EXCLUDED.report_template, logo_data=CASE WHEN $7 THEN NULL WHEN $8 THEN EXCLUDED.logo_data ELSE depannhome_billing_profiles.logo_data END, logo_mime_type=CASE WHEN $7 THEN '' WHEN $8 THEN EXCLUDED.logo_mime_type ELSE depannhome_billing_profiles.logo_mime_type END, report_secondary_logo_data=CASE WHEN $9 THEN NULL WHEN $10 THEN EXCLUDED.report_secondary_logo_data ELSE depannhome_billing_profiles.report_secondary_logo_data END, report_secondary_logo_mime_type=CASE WHEN $9 THEN '' WHEN $10 THEN EXCLUDED.report_secondary_logo_mime_type ELSE depannhome_billing_profiles.report_secondary_logo_mime_type END, updated_at=NOW()`, [ownerId, JSON.stringify(template), primaryLogo?.buffer || null, primaryLogo?.mimetype || "", secondaryLogo?.buffer || null, secondaryLogo?.mimetype || "", removePrimaryLogo, Boolean(primaryLogo), removeSecondaryLogo, Boolean(secondaryLogo)]);
        response.status(204).end();
    }));
    app.get("/api/technical-reports/appointments/:appointmentId", asyncHandler(async (request, response) => {
        const appointment = await findAccessibleAppointment(getAccountOwnerId(request), positiveId(request.params.appointmentId), request);
        if (!appointment) return response.status(404).json({ message: "Intervention introuvable ou non accessible." });
        const report = await findByAppointment(getAccountOwnerId(request), appointment.id, request);
        response.json({ appointment, report });
    }));
    app.post("/api/technical-reports", asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const input = sanitizeReport(request.body);
        if (!input.ok) return response.status(400).json({ message: input.message });
        const appointment = input.appointmentId ? await findAccessibleAppointment(ownerId, input.appointmentId, request) : null;
        if (!appointment) return response.status(400).json({ message: "Créez le rapport depuis une intervention rattachée à un dossier client." });
        const clientId = await findClientId(ownerId, input.clientId, appointment.clientName);
        if (!clientId) return response.status(400).json({ message: "Créez ou sélectionnez d’abord le dossier client de cette intervention." });
        const snapshot = await buildReportSnapshot(ownerId, appointment, clientId, request);
        const content = normalizeLeakContent({ ...input.content, snapshot }, snapshot);
        const { rows } = await getPool().query(`INSERT INTO depannhome_technical_reports (owner_id, created_by, appointment_id, client_id, report_type, title, report_date, content) VALUES ($1,$2,$3,$4,$5,$6,$7::date,$8::jsonb) RETURNING id`, [ownerId, request.user.sub, appointment?.id || null, clientId, REPORT_TYPE, input.title, input.reportDate, JSON.stringify(content)]);
        await publishEvent(request, reportTarget(rows[0].id), "report_started", { appointmentId: appointment.id });
        await recordMissionEventForSource({ ownerId, sourceType: "appointment", sourceId: appointment.id, status: "report_in_progress", action: "report_started", actorName: request.user.fullName || request.user.username });
        response.status(201).json({ id: rows[0].id });
    }));
    app.get("/api/technical-reports/:reportId", asyncHandler(async (request, response) => {
        const report = await findReport(getAccountOwnerId(request), positiveId(request.params.reportId), request);
        if (!report) return response.status(404).json({ message: "Rapport introuvable." });
        response.json({ report, corrections: await loadCorrections(getAccountOwnerId(request), report.id), lock: await getLock(getAccountOwnerId(request), "technical_report", String(report.id)), audit: await getAudit(getAccountOwnerId(request), "technical_report", String(report.id)) });
    }));
    app.put("/api/technical-reports/:reportId", asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request);
        if (!report) return response.status(404).json({ message: "Rapport introuvable." });
        const input = sanitizeReport(request.body);
        if (!input.ok) return response.status(400).json({ message: input.message });
        if (!canEdit(report, request)) return response.status(409).json({ message: "Ce rapport ne peut pas être modifié dans son état actuel." });
        if (!await enforceReportLock(request, response, report.id)) return;
        await getPool().query("UPDATE depannhome_technical_reports SET title=$3, report_date=$4::date, content=$5::jsonb, status=CASE WHEN status='in_correction' THEN 'draft' ELSE status END, updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, ownerId, input.title, input.reportDate, JSON.stringify(input.content)]);
        await publishEvent(request, reportTarget(report.id), "report_saved", { status: report.status });
        await recordMissionEventForSource({ ownerId, sourceType: "report", sourceId: report.id, status: "report_in_progress", action: "report_saved", actorName: request.user.fullName || request.user.username });
        response.status(204).end();
    }));
    app.post("/api/technical-reports/:reportId/proofread", requireReportProofreadingAccess, asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request);
        if (!report) return response.status(404).json({ message: "Rapport introuvable." });
        const input = sanitizeReport(request.body);
        if (!input.ok) return response.status(400).json({ message: input.message });
        if (!canEdit(report, request)) return response.status(409).json({ message: "Ce rapport ne peut pas être modifié dans son état actuel." });
        if (!await enforceReportLock(request, response, report.id)) return;
        if (report.status !== "submitted") return response.status(409).json({ message: "Terminez d’abord le rapport sur mobile avant de le corriger sur un poste PC." });
        const fingerprint = reportProofreadingFingerprint({ ...report, title: input.title, reportDate: input.reportDate, content: input.content });
        const { rows } = await getPool().query("UPDATE depannhome_technical_reports SET title=$3, report_date=$4::date, content=$5::jsonb, status='ready_to_send', proofread_at=NOW(), proofread_by=$6, proofread_fingerprint=$7, updated_at=NOW() WHERE id=$1 AND owner_id=$2 RETURNING proofread_at AS \"proofreadAt\"", [report.id, ownerId, input.title, input.reportDate, JSON.stringify(input.content), request.user.sub, fingerprint]);
        await publishEvent(request, reportTarget(report.id), "report_proofread", { status: "ready_to_send" });
        response.json({ message: "Rapport corrigé : il peut maintenant être envoyé.", proofreadAt: rows[0]?.proofreadAt || null });
    }));
    app.post("/api/technical-reports/:reportId/pdf-preview", requireReportProofreadingAccess, asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request);
        if (!report) return response.status(404).json({ message: "Rapport introuvable." });
        const input = sanitizeReport(request.body);
        if (!input.ok) return response.status(400).json({ message: input.message });
        if (!canEdit(report, request)) return response.status(409).json({ message: "Ce rapport ne peut pas être prévisualisé dans son état actuel." });
        if (!await enforceReportLock(request, response, report.id)) return;
        const profile = await loadProfile(ownerId);
        const draft = { ...report, title: input.title, reportDate: input.reportDate, content: input.content };
        const policy = ["integrated_only", "company_choice", "external_only"].includes(profile.reportTemplatePolicy) ? profile.reportTemplatePolicy : "company_choice";
        const externalDocx = profile.reportFileTemplateMimeType === "application/vnd.openxmlformats-officedocument.wordprocessingml.document" && (policy === "external_only" || (policy !== "integrated_only" && profile.reportFileTemplateMode === "external"));
        const output = externalDocx
            ? { buffer: await createWizardLeakReportPdf(draft, profile), mimeType: PDF_MIME }
            : await createTechnicalReportOutput(draft, profile);
        response.set({ "Content-Type": PDF_MIME, "Content-Disposition": "inline", "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff", "X-Report-Preview-Mode": externalDocx ? "business-pages" : "final" });
        response.send(output.buffer);
    }));
    app.post("/api/technical-reports/:reportId/media", upload.array("files", 5), asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request);
        const section = allowedSection(report, request.body?.section) ? String(request.body.section) : ""; const files = Array.isArray(request.files) ? request.files : [];
        if (!report) return response.status(404).json({ message: "Rapport introuvable." });
        if (!canEdit(report, request)) return response.status(409).json({ message: "Le rapport est verrouillé." });
        if (!await enforceReportLock(request, response, report.id)) return;
        if (!section || !files.length) return response.status(400).json({ message: "Section et photo(s) obligatoires." });
        const media = Array.isArray(report.media) ? report.media : [];
        if (media.length + files.length > MAX_MEDIA_PER_REPORT) return response.status(400).json({ message: `Le rapport est limité à ${MAX_MEDIA_PER_REPORT} photos.` });
        const observationId = cleanText(request.body?.observationId, 100); const materialId = cleanText(request.body?.materialId, 100); const lastSortOrder = Math.max(-1, ...media.map(item => Number(item.sortOrder) || 0));
        const additions = files.map((file, index) => ({ id: `media-${crypto.randomUUID()}`, section, observationId, materialId, sortOrder: lastSortOrder + index + 1, pdfSize: "large", name: safeName(file.originalname), mime: file.mimetype, size: file.size, caption: cleanText(request.body?.caption, 500), annotation: cleanText(request.body?.annotation, 1000), dataUrl: `data:${file.mimetype};base64,${file.buffer.toString("base64")}`, createdAt: new Date().toISOString() }));
        const next = [...media, ...additions]; if (Buffer.byteLength(JSON.stringify(next)) > MAX_REPORT_BYTES) return response.status(400).json({ message: "Le rapport est trop volumineux : compressez les photos." });
        await getPool().query("UPDATE depannhome_technical_reports SET media=$3::jsonb, updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, ownerId, JSON.stringify(next)]);
        const { registerMissionSourceItem } = await import("./partner-dialogue.js"); await Promise.all(additions.map(photo => registerMissionSourceItem({ ownerId, appointmentId: report.appointmentId, sourceType: "photo", sourceId: report.id, sourceItemId: photo.id, label: photo.name, details: { section: photo.section, caption: photo.caption } })));
        await publishEvent(request, reportTarget(report.id), "report_media_added", { count: additions.length, section });
        response.status(201).json({ media: additions });
    }));
    app.patch("/api/technical-reports/:reportId/media/:mediaId", asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request); if (!report) return response.status(404).json({ message: "Rapport introuvable." }); if (!canEdit(report, request)) return response.status(409).json({ message: "Le rapport est verrouillé." }); if (!await enforceReportLock(request, response, report.id)) return;
        const id = String(request.params.mediaId || ""); const annotatedImage = /^data:image\/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$/.test(String(request.body?.dataUrl || "")) && Buffer.byteLength(String(request.body.dataUrl), "utf8") <= MAX_MEDIA_SIZE * 1.4 ? String(request.body.dataUrl) : ""; const requestedSortOrder = Number(request.body?.sortOrder); const requestedPdfSize = ["compact", "medium", "large"].includes(request.body?.pdfSize) ? request.body.pdfSize : ""; const media = (report.media || []).map(item => item.id === id ? { ...item, caption: cleanText(request.body?.caption, 500), annotation: cleanText(request.body?.annotation, 1000), observationId: cleanText(request.body?.observationId, 100) || item.observationId || "", materialId: cleanText(request.body?.materialId, 100) || item.materialId || "", ...(Number.isFinite(requestedSortOrder) && requestedSortOrder >= 0 ? { sortOrder: requestedSortOrder } : {}), ...(requestedPdfSize ? { pdfSize: requestedPdfSize } : {}), ...(annotatedImage ? { dataUrl: annotatedImage, name: safeName(request.body?.name || item.name), mime: ["image/jpeg", "image/png", "image/webp"].includes(request.body?.mime) ? request.body.mime : item.mime, size: Math.min(MAX_MEDIA_SIZE, Math.max(0, Number(request.body?.size) || item.size || 0)) } : {}) } : item); if (!media.some(item => item.id === id)) return response.status(404).json({ message: "Photo introuvable." });
        await getPool().query("UPDATE depannhome_technical_reports SET media=$3::jsonb, updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, ownerId, JSON.stringify(media)]); await publishEvent(request, reportTarget(report.id), "report_media_updated", { mediaId: id }); response.status(204).end();
    }));
    app.post("/api/technical-reports/:reportId/sections/:sectionId/duplicate-media", asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request); const sourceSection = String(request.params.sectionId || ""); const targetSection = String(request.body?.targetSection || "");
        if (!report) return response.status(404).json({ message: "Rapport introuvable." });
        if (!canEdit(report, request)) return response.status(409).json({ message: "Le rapport est verrouillé." });
        if (!await enforceReportLock(request, response, report.id)) return;
        if (!allowedSection(report, sourceSection) || !allowedSection(report, targetSection)) return response.status(400).json({ message: "Section de duplication invalide." });
        const media = Array.isArray(report.media) ? report.media : []; const source = media.filter(item => item.section === sourceSection);
        if (media.length + source.length > MAX_MEDIA_PER_REPORT) return response.status(400).json({ message: `Le rapport est limité à ${MAX_MEDIA_PER_REPORT} photos.` });
        const lastSortOrder = Math.max(-1, ...media.map(item => Number(item.sortOrder) || 0));
        const copies = source.map((item, index) => ({ ...item, id: `media-${crypto.randomUUID()}`, section: targetSection, materialId: "", sortOrder: lastSortOrder + index + 1, createdAt: new Date().toISOString() }));
        const next = [...media, ...copies]; if (Buffer.byteLength(JSON.stringify(next)) > MAX_REPORT_BYTES) return response.status(400).json({ message: "Le rapport est trop volumineux : les photos ne peuvent pas être dupliquées." });
        await getPool().query("UPDATE depannhome_technical_reports SET media=$3::jsonb, updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, ownerId, JSON.stringify(next)]);
        await publishEvent(request, reportTarget(report.id), "report_media_added", { count: copies.length, section: targetSection, duplicatedFrom: sourceSection });
        response.status(201).json({ media: copies });
    }));
    app.delete("/api/technical-reports/:reportId/media/:mediaId", asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request); if (!report) return response.status(404).json({ message: "Rapport introuvable." }); if (!canEdit(report, request)) return response.status(409).json({ message: "Le rapport est verrouillé." }); if (!await enforceReportLock(request, response, report.id)) return;
        const media = (report.media || []).filter(item => item.id !== String(request.params.mediaId || "")); await getPool().query("UPDATE depannhome_technical_reports SET media=$3::jsonb, updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, ownerId, JSON.stringify(media)]); await publishEvent(request, reportTarget(report.id), "report_media_deleted"); response.status(204).end();
    }));
    app.post("/api/technical-reports/:reportId/submit", asyncHandler(async (request, response) => {
        const report = await findReport(getAccountOwnerId(request), positiveId(request.params.reportId), request); if (!report) return response.status(404).json({ message: "Rapport introuvable." }); if (!canEdit(report, request)) return response.status(409).json({ message: "Le rapport est verrouillé." }); if (!await enforceReportLock(request, response, report.id)) return;
        if (!["draft", "in_correction"].includes(report.status)) return response.status(409).json({ message: "Ce rapport a déjà été terminé." });
        await getPool().query("UPDATE depannhome_technical_reports SET status='submitted', submitted_at=NOW(), updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, getAccountOwnerId(request)]);
        await publishEvent(request, reportTarget(report.id), "report_submitted", {}, await administrationNotifications(getAccountOwnerId(request), request.user.sub, "Rapport terminé à corriger", `Le rapport #${report.id} est terminé et attend sa correction sur un poste PC.`));
        await releaseLock(request, "technical_report", String(report.id), "lock_released_after_submission"); response.status(204).end();
    }));
    app.post("/api/technical-reports/:reportId/corrections", requireReportAdministration, asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request); const section = allowedSection(report, request.body?.section) ? String(request.body.section) : ""; const comment = cleanText(request.body?.comment, 2000);
        if (!report) return response.status(404).json({ message: "Rapport introuvable." }); if (!section || !comment) return response.status(400).json({ message: "Section et commentaire obligatoires." }); if (!await enforceReportLock(request, response, report.id)) return;
        await getPool().query("INSERT INTO depannhome_technical_report_corrections (owner_id, report_id, section_key, comment, requested_by) VALUES ($1,$2,$3,$4,$5)", [ownerId, report.id, section, comment, request.user.sub]);
        await getPool().query("UPDATE depannhome_technical_reports SET status='in_correction', proofread_at=NULL, proofread_by=NULL, proofread_fingerprint='', updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, ownerId]);
        await notifyTechnician(ownerId, report, request.user.sub, section, comment); await publishEvent(request, reportTarget(report.id), "report_correction_requested", { section }, report.createdBy ? [{ recipientId: report.createdBy, title: "Corrections demandées", body: `Le rapport #${report.id} requiert une correction dans « ${section} ».`, eventType: "report_correction_requested" }] : []); response.status(201).end();
    }));
    app.post("/api/technical-reports/:reportId/validate", requireReportValidationAccess, asyncHandler(async (request, response) => {
        const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request, false, true); if (!report) return response.status(404).json({ message: "Rapport introuvable." }); if (report.status !== "ready_to_send") return response.status(409).json({ message: "Corrigez le rapport sur un poste PC avant son envoi définitif." }); if (!await enforceReportLock(request, response, report.id)) return;
        if (!isReportProofreadingCurrent(report)) return response.status(409).json({ message: "La correction PC doit être enregistrée avant l’envoi définitif." });
        const profile = await loadProfile(ownerId); const output = await createTechnicalReportOutput(report, profile);
        let archivedAttachment = null; const connection = await getPool().connect(); try { await connection.query("BEGIN"); await connection.query("UPDATE depannhome_technical_reports SET status='validated', validated_at=NOW(), validated_by=$3, pdf_data=$4, pdf_filename=$5, document_mime_type=$6, updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, ownerId, request.user.sub, output.buffer, output.filename, output.mimeType]); archivedAttachment = await archiveDocument(connection, ownerId, report, output, request); await connection.query("COMMIT"); } catch (error) { await connection.query("ROLLBACK"); throw error; } finally { connection.release(); }
        await synchronizeConnectedReport(ownerId, report.id);
        const { registerMissionSourceItem } = await import("./partner-dialogue.js"); await registerMissionSourceItem({ ownerId, appointmentId: report.appointmentId, sourceType: "report", sourceId: report.id, label: report.title, details: { status: "validated", reportDate: report.reportDate } });
        await recordMissionEventForSource({ ownerId, sourceType: "report", sourceId: report.id, status: "report_validated", action: "report_validated", actorName: request.user.fullName || request.user.username });
        await publishEvent(request, reportTarget(report.id), "report_validated", { pdfGenerated: true }, report.createdBy ? [{ recipientId: report.createdBy, title: "Rapport validé", body: `Le rapport #${report.id} a été validé et son PDF a été archivé.`, eventType: "report_validated" }] : []);
        response.json({ message: "Rapport corrigé et validé", reportId: report.id, clientId: report.clientId || "", attachmentId: archivedAttachment?.id || "" });
    }));
    app.post("/api/technical-reports/:reportId/reopen", requireReportAdministration, asyncHandler(async (request, response) => { const ownerId = getAccountOwnerId(request); const report = await findReport(ownerId, positiveId(request.params.reportId), request); if (!report) return response.status(404).json({ message: "Rapport introuvable." }); if (!await enforceReportLock(request, response, report.id)) return; await getPool().query("UPDATE depannhome_technical_reports SET status='draft', proofread_at=NULL, proofread_by=NULL, proofread_fingerprint='', pdf_data=NULL, pdf_filename='', validated_at=NULL, validated_by=NULL, updated_at=NOW() WHERE id=$1 AND owner_id=$2", [report.id, ownerId]); await publishEvent(request, reportTarget(report.id), "report_reopened", {}, report.createdBy ? [{ recipientId: report.createdBy, title: "Rapport remis en brouillon", body: `Le rapport #${report.id} a été remis en brouillon.`, eventType: "report_reopened" }] : []); response.status(204).end(); }));
    app.get("/api/technical-reports/:reportId/pdf", asyncHandler(async (request, response) => { const report = await findReport(getAccountOwnerId(request), positiveId(request.params.reportId), request, true); if (!report) return response.status(404).json({ message: "Rapport introuvable." }); const output = report.pdfData ? { buffer: report.pdfData, filename: report.pdfFilename || `rapport-recherche-fuite-${report.id}.pdf`, mimeType: report.documentMimeType || PDF_MIME } : await createTechnicalReportOutput(report, await loadProfile(getAccountOwnerId(request))); response.set({ "Content-Type": output.mimeType, "Content-Disposition": `${output.mimeType === PDF_MIME ? "inline" : "attachment"}; filename*=UTF-8''${encodeURIComponent(output.filename)}`, "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff" }); response.send(output.buffer); }));
    app.post("/api/technical-reports/library", requireReportAdministration, asyncHandler(async (request, response) => { const item = sanitizeLibraryItem(request.body); if (!item.ok) return response.status(400).json({ message: item.message }); const ownerId = getAccountOwnerId(request); const count = await getPool().query("SELECT count(*)::int AS count FROM depannhome_technical_report_library WHERE owner_id=$1", [ownerId]); if (count.rows[0].count >= MAX_LIBRARY_ITEMS) return response.status(400).json({ message: "Bibliothèque complète." }); const { rows } = await getPool().query("INSERT INTO depannhome_technical_report_library (owner_id, category, label, content) VALUES ($1,$2,$3,$4::jsonb) RETURNING id", [ownerId, item.category, item.label, JSON.stringify(item.content)]); response.status(201).json({ id: rows[0].id }); }));
    app.delete("/api/technical-reports/library/:itemId", requireReportAdministration, asyncHandler(async (request, response) => { const result = await getPool().query("DELETE FROM depannhome_technical_report_library WHERE id=$1 AND owner_id=$2", [positiveId(request.params.itemId), getAccountOwnerId(request)]); if (!result.rowCount) return response.status(404).json({ message: "Élément introuvable." }); response.status(204).end(); }));
}

function requireReportAccess(request, response, next) { if (request.user?.role === "accountant") return response.status(403).json({ message: "L’espace comptabilité n’accède pas aux rapports techniques." }); return next(); }
function requireReportAdministration(request, response, next) { if (!["admin", "mobile_admin"].includes(request.user?.role)) return response.status(403).json({ message: "Cette action est réservée au personnel administratif." }); return next(); }
function requireReportProofreadingAccess(request, response, next) { if (!canConfirmReportProofreading(request.user?.role, request.user?.deviceType)) return response.status(403).json({ message: "La correction finale du rapport est réservée à un poste PC autorisé." }); return next(); }
function requireReportValidationAccess(request, response, next) { if (!canConfirmReportProofreading(request.user?.role, request.user?.deviceType)) return response.status(403).json({ message: "L’envoi définitif du rapport est réservé à un poste PC autorisé." }); return next(); }
async function enforceReportLock(request, response, reportId) { const result = await assertLockOwner(request, "technical_report", String(reportId)); if (result.ok) return true; response.status(409).json({ message: result.message, lock: result.lock || null }); return false; }
function reportTarget(reportId) { return { entityType: "technical_report", entityId: String(reportId) }; }
async function administrationNotifications(ownerId, senderId, title, body) { const { rows } = await getPool().query("SELECT id FROM depannhome_users WHERE account_owner_id=$1 AND role IN ('admin', 'mobile_admin') AND is_active=TRUE AND id<>$2", [ownerId, senderId]); return rows.map(row => ({ recipientId: row.id, title, body })); }
async function loadReports(ownerId, request) { const { rows } = await getPool().query(`SELECT report.id, report.appointment_id AS "appointmentId", report.client_id AS "clientId", report.title, TO_CHAR(report.report_date,'YYYY-MM-DD') AS "reportDate", report.status, report.created_by AS "createdBy", report.created_at AS "createdAt", report.updated_at AS "updatedAt", creator.full_name AS "technicianName", COALESCE(NULLIF(report.content->'snapshot'->>'clientName',''), event.client_name, client.client_data->>'name', '') AS "clientName", COALESCE(NULLIF(report.content->'snapshot'->>'claimNumber',''), client.client_data->>'claimNumber', client.client_data->>'claim', '') AS "claimNumber", COALESCE(NULLIF(report.content->'snapshot'->>'insurance',''), client.client_data->>'insurance', client.client_data->>'insurer', '') AS insurance FROM depannhome_technical_reports report LEFT JOIN depannhome_users creator ON creator.id=report.created_by LEFT JOIN depannhome_calendar_events event ON event.id=report.appointment_id AND event.owner_id=report.owner_id LEFT JOIN depannhome_clients client ON client.owner_id=report.owner_id AND client.client_id=report.client_id WHERE report.owner_id=$1 AND ($2 NOT IN ('technician','team_lead') OR report.created_by=$3 OR EXISTS (SELECT 1 FROM depannhome_calendar_assignments assignment WHERE assignment.event_id=report.appointment_id AND assignment.technician_id=$3)) ORDER BY report.updated_at DESC`, [ownerId, request.user.role, request.user.sub]); return rows; }
async function findReport(ownerId, id, request, includePdf = false, includeProofreadingFingerprint = false) { if (!id) return null; const { rows } = await getPool().query(`SELECT report.*, report.appointment_id AS "appointmentId", report.client_id AS "clientId", TO_CHAR(report.report_date,'YYYY-MM-DD') AS "reportDate", report.created_by AS "createdBy", report.pdf_data AS "pdfData", report.pdf_filename AS "pdfFilename", report.document_mime_type AS "documentMimeType", creator.full_name AS "technicianName", event.client_name AS "clientName", event.location AS "appointmentLocation", TO_CHAR(event.event_date,'YYYY-MM-DD') AS "appointmentDate", TO_CHAR(event.start_time,'HH24:MI') AS "appointmentStartTime", client.client_data->>'phone' AS "clientPhone", CONCAT_WS(', ', NULLIF(client.client_data->>'address',''), NULLIF(client.client_data->>'city','')) AS "clientAddress" FROM depannhome_technical_reports report LEFT JOIN depannhome_users creator ON creator.id=report.created_by LEFT JOIN depannhome_calendar_events event ON event.id=report.appointment_id AND event.owner_id=report.owner_id LEFT JOIN depannhome_clients client ON client.owner_id=report.owner_id AND client.client_id=report.client_id WHERE report.id=$1 AND report.owner_id=$2 AND ($3 NOT IN ('technician','team_lead') OR report.created_by=$4 OR EXISTS (SELECT 1 FROM depannhome_calendar_assignments assignment WHERE assignment.event_id=report.appointment_id AND assignment.technician_id=$4))`, [id, ownerId, request.user.role, request.user.sub]); return rows[0] ? publicReport(rows[0], includePdf, includeProofreadingFingerprint) : null; }
async function findByAppointment(ownerId, appointmentId, request) { const { rows } = await getPool().query(`SELECT id FROM depannhome_technical_reports WHERE owner_id=$1 AND appointment_id=$2 ORDER BY updated_at DESC LIMIT 1`, [ownerId, appointmentId]); return rows[0] ? findReport(ownerId, rows[0].id, request) : null; }
function publicReport(report, includePdf = false, includeProofreadingFingerprint = false) { const legacySections = { cover: "overview", installation: "visual", measurements: "humidity", leakSearch: "methods", location: "conclusion", work: "conclusion", finalControl: "waterTest", signatures: "recommendations" }; const value = { ...report, content: normalizeContent(report.content), media: (Array.isArray(report.media) ? report.media : []).map(item => ({ ...item, section: legacySections[item.section] || item.section })), proofreadAt: report.proofread_at || null, proofreadBy: report.proofread_by || null }; value.proofreadCurrent = isReportProofreadingCurrent(value); delete value.proofread_at; delete value.proofread_by; if (!includeProofreadingFingerprint) delete value.proofread_fingerprint; if (!includePdf) delete value.pdfData; return value; }
function allowedSection(report, section) { return report && reportSections(report.content, true).some(item => item.id === String(section || "")); }
async function findAccessibleAppointment(ownerId, id, request) { if (!id) return null; const { rows } = await getPool().query(`SELECT event.id, event.client_name AS "clientName", event.location, event.title, TO_CHAR(event.event_date,'YYYY-MM-DD') AS date, TO_CHAR(event.start_time,'HH24:MI') AS "startTime", event.notes, COALESCE(technician.full_name, technician.username, '') AS "assignedTechnicianName" FROM depannhome_calendar_events event LEFT JOIN depannhome_users technician ON technician.id=event.assigned_technician_id WHERE event.id=$1 AND event.owner_id=$2 AND event.event_type='appointment' AND ($3 NOT IN ('technician','team_lead') OR EXISTS (SELECT 1 FROM depannhome_calendar_assignments assignment WHERE assignment.event_id=event.id AND assignment.technician_id=$4))`, [id, ownerId, request.user.role, request.user.sub]); return rows[0] || null; }
async function buildReportSnapshot(ownerId, appointment, clientId, request) { const profile = await loadProfile(ownerId); const clientResult = clientId ? await getPool().query("SELECT client_data AS client FROM depannhome_clients WHERE owner_id=$1 AND client_id=$2", [ownerId, clientId]) : { rows: [] }; const client = clientResult.rows[0]?.client || {}; return { companyName: profile.companyName || request.user.companyName || "", companyAddress: [profile.address, profile.postalCode, profile.city].filter(Boolean).join(", "), companyPhone: profile.phone || "", companyEmail: profile.email || "", interventionNumber: String(appointment.id), interventionReference: appointment.title || "", interventionType: appointment.title || "Intervention", date: appointment.date || "", time: appointment.startTime || "", notes: appointment.notes || "", clientName: client.name || appointment.clientName || "", clientAddress: [client.address, client.postalCode, client.city].filter(Boolean).join(", ") || appointment.location || "", clientPhone: client.phone || "", clientEmail: client.email || "", technicianName: request.user.fullName || request.user.username || appointment.assignedTechnicianName || "", technicianPhone: request.user.phone || "", insurance: client.insurance || client.insurer || "", claimNumber: client.claimNumber || client.claim || "", expert: client.expert || "", manager: client.manager || client.caseManager || "" }; }
async function findClientId(ownerId, requested, name) { const requestedId = CLIENT_ID.test(String(requested || "")) ? String(requested) : ""; const { rows } = await getPool().query("SELECT client_id FROM depannhome_clients WHERE owner_id=$1 AND client_status='active' AND (($2<>'' AND client_id=$2) OR ($2='' AND LOWER(BTRIM(client_data->>'name'))=LOWER(BTRIM($3)))) LIMIT 1", [ownerId, requestedId, name || ""]); return rows[0]?.client_id || ""; }
async function loadCorrections(ownerId, reportId) { const { rows } = await getPool().query(`SELECT correction.id, correction.section_key AS section, correction.comment, correction.resolved_at AS "resolvedAt", correction.created_at AS "createdAt", user_account.full_name AS "requestedBy" FROM depannhome_technical_report_corrections correction LEFT JOIN depannhome_users user_account ON user_account.id=correction.requested_by WHERE correction.owner_id=$1 AND correction.report_id=$2 ORDER BY correction.created_at DESC`, [ownerId, reportId]); return rows; }
async function loadLibrary(ownerId) { const { rows } = await getPool().query("SELECT id, category, label, content FROM depannhome_technical_report_library WHERE owner_id=$1 ORDER BY category, LOWER(label)", [ownerId]); return rows; }
function canEdit(report, request) { const isOwnerOrAdministration = ["admin", "mobile_admin"].includes(request.user.role) || Number(report.createdBy) === Number(request.user.sub); if (["draft", "in_correction"].includes(report.status)) return isOwnerOrAdministration; return report.status === "submitted" && canConfirmReportProofreading(request.user?.role, request.user?.deviceType); }
async function notifyTechnician(ownerId, report, senderId, section, comment) { if (!report.createdBy || Number(report.createdBy) === Number(senderId)) return; await getPool().query("INSERT INTO depannhome_messages (sender_id, recipient_id, client_id, body) VALUES ($1,$2,$3,$4)", [senderId, report.createdBy, report.clientId || null, `Correction demandée — rapport fuite #${report.id}, section ${section} : ${comment}`.slice(0, 2000)]); }
function sanitizeReport(value) { const appointmentId = positiveId(value?.appointmentId); const title = cleanText(value?.title, 160) || "Rapport de recherche de fuite"; const reportDate = validDate(value?.reportDate) || new Date().toISOString().slice(0, 10); return { ok: true, appointmentId, clientId: cleanText(value?.clientId, 100), title, reportDate, content: normalizeContent(value?.content) }; }
function normalizeContent(value) { return normalizeLeakContent(value); }
function sanitizeLibraryItem(value) { const category = cleanText(value?.category, 40); const label = cleanText(value?.label, 160); const content = value?.content && typeof value.content === "object" && !Array.isArray(value.content) ? value.content : {}; return category && label ? { ok: true, category, label, content } : { ok: false, message: "Catégorie et libellé obligatoires." }; }
async function loadProfile(ownerId) { const { rows } = await getPool().query("SELECT profile.company_name AS \"companyName\", profile.address, profile.postal_code AS \"postalCode\", profile.city, profile.phone, profile.email, profile.registration_number AS \"registrationNumber\", profile.tax_number AS \"taxNumber\", profile.logo_data AS \"logoData\", profile.logo_mime_type AS \"logoMimeType\", profile.report_template AS \"reportTemplate\", profile.report_secondary_logo_data AS \"secondaryLogoData\", profile.report_secondary_logo_mime_type AS \"secondaryLogoMimeType\", profile.report_file_template_mode AS \"reportFileTemplateMode\", profile.report_file_template_filename AS \"reportFileTemplateFilename\", profile.report_file_template_data AS \"reportFileTemplateData\", profile.report_file_template_mime_type AS \"reportFileTemplateMimeType\", owner.report_template_policy AS \"reportTemplatePolicy\" FROM depannhome_users owner LEFT JOIN depannhome_billing_profiles profile ON profile.owner_id=owner.id WHERE owner.id=$1", [ownerId]); return rows[0] || {}; }
async function loadReportTemplate(ownerId) { const profile = await loadProfile(ownerId); return { ...defaultReportTemplate(), ...(profile.reportTemplate || {}), hasPrimaryLogo: Boolean(profile.logoData), hasSecondaryLogo: Boolean(profile.secondaryLogoData) }; }
function defaultReportTemplate() { return { companyName: "", address: "", phone: "", email: "", website: "", siret: "", vat: "", legalNotice: "", headerText: "", footerText: "", primaryColor: "#003b73", secondaryColor: "#0a5c36", titleColor: "#003b73", separatorColor: "#0a5c36", font: "Helvetica", footerFields: ["address", "phone", "email", "website", "siret", "vat", "legalNotice"], hasSecondaryLogo: false }; }
function sanitizeReportTemplate(value) { const base = defaultReportTemplate(); const colors = ["primaryColor", "secondaryColor", "titleColor", "separatorColor"]; for (const key of colors) base[key] = /^#[0-9a-fA-F]{6}$/.test(String(value?.[key] || "")) ? String(value[key]) : base[key]; for (const [key, max] of Object.entries({ companyName: 160, address: 255, phone: 50, email: 160, website: 160, siret: 100, vat: 100, legalNotice: 1000, headerText: 500, footerText: 500 })) base[key] = cleanText(value?.[key], max); base.font = ["Helvetica", "Times-Roman", "Courier"].includes(value?.font) ? value.font : base.font; base.footerFields = [...new Set((Array.isArray(value?.footerFields) ? value.footerFields : [value?.footerFields]).filter(item => ["address", "phone", "email", "website", "siret", "vat", "legalNotice"].includes(item)))]; return base; }
async function archiveDocument(connection, ownerId, report, output, request) { if (!report.clientId) return null; const { rows } = await connection.query("SELECT client_data AS client FROM depannhome_clients WHERE owner_id=$1 AND client_id=$2 FOR UPDATE", [ownerId, report.clientId]); const client = rows[0]?.client; if (!client) return null; const attachments = Array.isArray(client.attachments) ? client.attachments : []; if (attachments.length >= 30) throw new Error("Le dossier client contient déjà le maximum de fichiers autorisés."); const createdAt = new Date().toISOString(); const attachment = { id: `file-${crypto.randomUUID()}`, type: "Rapport fuite", name: output.filename, mime: output.mimeType, size: output.buffer.length, reportId: String(report.id), appointmentId: report.appointmentId || undefined, createdAt }; const history = Array.isArray(client.activityHistory) ? client.activityHistory : []; const updated = { ...client, attachments: [...attachments, attachment], activityHistory: [{ id: `activity-${crypto.randomUUID()}`, type: "technical_report", label: "Rapport de recherche de fuite validé", detail: output.filename, attachmentId: attachment.id, actorName: String(request.user.fullName || request.user.username || "Administration").slice(0, 100), createdAt }, ...history].slice(0, 150), updatedAt: createdAt }; await connection.query("UPDATE depannhome_clients SET client_data=$3::jsonb, updated_at=NOW() WHERE owner_id=$1 AND client_id=$2", [ownerId, report.clientId, JSON.stringify(updated)]); return attachment; }

export async function createTechnicalReportOutput(report, profile) { const generatedPdf = await createWizardLeakReportPdf(report, profile); const policy = ["integrated_only", "company_choice", "external_only"].includes(profile.reportTemplatePolicy) ? profile.reportTemplatePolicy : "company_choice"; const external = policy === "external_only" || (policy !== "integrated_only" && profile.reportFileTemplateMode === "external"); if (!external) return { buffer: generatedPdf, filename: `rapport-recherche-fuite-${report.id}.pdf`, mimeType: PDF_MIME }; const snapshot = report.content?.snapshot || {}; return renderCompanyTemplate({ buffer: profile.reportFileTemplateData, filename: profile.reportFileTemplateFilename || `rapport-recherche-fuite-${report.id}.pdf`, mimeType: profile.reportFileTemplateMimeType, generatedPdf, values: { numero_rapport: report.id, titre: report.title, date: report.reportDate, client_nom: report.clientName || snapshot.clientName, client_adresse: report.clientAddress || report.appointmentLocation || snapshot.clientAddress, technicien: report.technicianName || snapshot.technicianName, entreprise_nom: profile.companyName, entreprise_adresse: [profile.address, profile.postalCode, profile.city].filter(Boolean).join(" "), entreprise_telephone: profile.phone, entreprise_email: profile.email, contenu: JSON.stringify(report.content || {}) } }); }

export function createLeakReportPdf(report, profile) { return new Promise((resolve, reject) => { const pdf = new PDFDocument({ size: "A4", margin: 44, bufferPages: true, info: { Title: report.title, Author: profile.companyName || "Depann'Home Pro" } }); const chunks = []; pdf.on("data", chunk => chunks.push(chunk)); pdf.on("end", () => resolve(Buffer.concat(chunks))); pdf.on("error", reject); const content = report.content; const media = report.media || []; const title = value => { pdf.fillColor("#003b73").font("Helvetica-Bold").fontSize(19).text(value); pdf.moveDown(.5); }; const paragraph = value => { if (value) pdf.fillColor("#172033").font("Helvetica").fontSize(9).text(String(value), { lineGap: 3 }); }; const section = (name, fields = []) => { pdf.addPage(); title(name); fields.forEach(([label, value]) => { if (value) { pdf.font("Helvetica-Bold").fontSize(9).fillColor("#003b73").text(label); paragraph(value); pdf.moveDown(.45); } }); addPhotos(pdf, media.filter(item => item.section === sectionKey(name)), 3); }; if (profile.logoData && ["image/png", "image/jpeg"].includes(profile.logoMimeType)) { try { pdf.image(profile.logoData, 44, 44, { fit: [75, 75] }); } catch {} } pdf.fillColor("#003b73").font("Helvetica-Bold").fontSize(25).text("RAPPORT DE RECHERCHE DE FUITE", 135, 50, { width: 415, align: "right" }); pdf.moveDown(5); pdf.fillColor("#172033").fontSize(12).text(profile.companyName || "Votre entreprise"); paragraph([profile.address, [profile.postalCode, profile.city].filter(Boolean).join(" "), profile.phone, profile.email].filter(Boolean).join("\n")); pdf.moveDown(2); title("Intervention"); paragraph(`Rapport n° ${report.id}\nClient : ${report.clientName || "Non renseigné"}\nAdresse : ${report.clientAddress || report.appointmentLocation || "Non renseignée"}\nTéléphone : ${report.clientPhone || "Non renseigné"}\nIntervention : ${formatDate(report.appointmentDate || report.reportDate)}${report.appointmentStartTime ? ` à ${report.appointmentStartTime}` : ""}\nTechnicien : ${report.technicianName || "Non renseigné"}\nAssurance : ${content.cover.insurance || "Non renseignée"}\nDossier : ${content.cover.claimNumber || "Non renseigné"}\nRéférence : ${content.cover.interventionReference || "Non renseignée"}`); addPhotos(pdf, media.filter(item => item.id === content.cover.generalPhotoId || item.section === "cover"), 1); pdf.addPage(); title("Sommaire"); ["État des lieux", "Description de l’installation", "Contrôle visuel", "Mesures techniques", "Recherche de fuite", "Localisation de la fuite", "Travaux réalisés", "Contrôle final", "Conclusion", "Signatures"].forEach((item, index) => paragraph(`${index + 1}. ${item}`)); section("État des lieux", [["Description générale", content.overview.generalDescription], ["Nature du sinistre", content.overview.incidentNature], ["Historique client", content.overview.customerHistory], ["Contexte", content.overview.context], ["Conditions d’intervention", content.overview.interventionConditions]]); section("Description de l’installation", [["Type", content.installation.installationType], ["Marque / modèle", [content.installation.brand, content.installation.model].filter(Boolean).join(" · ")], ["Année", content.installation.year], ["Fluide frigorigène", content.installation.refrigerant], ["N° de série", content.installation.serialNumber], ["Puissance", content.installation.power]]); section("Contrôle visuel", [["Check-list", (content.visual.checklist || []).map(item => `${item.label || item}: ${item.checked ? "conforme" : "à contrôler"}`).join("\n")], ["Observations", content.visual.observations], ["Anomalies constatées", content.visual.anomalies]]); tablePage(pdf, "Mesures techniques", content.measurements.rows, media.filter(item => item.section === "measurements")); section("Recherche de fuite", (content.leakSearch.methods || []).map(item => [item.name || "Méthode", `${item.result || ""}\n${item.observations || ""}\n${item.comments || ""}`])); section("Localisation de la fuite", [["Description précise", content.location.description], ["Localisation", content.location.preciseLocation], ["Commentaires", content.location.comments]]); section("Travaux réalisés", [["Réparation", content.work.repair], ["Remplacement", content.work.replacement], ["Recharge", content.work.recharge], ["Quantité de fluide", content.work.refrigerantQuantity], ["Essais", content.work.tests], ["Matériel", content.work.equipment]]); tablePage(pdf, "Contrôle final", content.finalControl.rows, media.filter(item => item.section === "finalControl")); section("Conclusion et préconisations", [["Contrôle d’étanchéité", content.finalControl.tightness], ["Essais de fonctionnement", content.finalControl.operatingTests], ["Validation", content.finalControl.validation], ["Préconisations", content.conclusion.recommendations]]); pdf.addPage(); title("Signatures"); paragraph(`Technicien : ${report.technicianName || ""}\nClient : ${content.signatures.clientName || report.clientName || ""}`); addSignature(pdf, content.signatures.technician, "Signature technicien", 70); addSignature(pdf, content.signatures.client, "Signature client", 280); const pages = pdf.bufferedPageRange(); for (let index = 0; index < pages.count; index += 1) { pdf.switchToPage(index); pdf.fillColor("#64748b").fontSize(7).text(`${profile.companyName || "Depann’Home Pro"} · Rapport #${report.id} · Page ${index + 1}/${pages.count}`, 44, pdf.page.height - 32, { width: pdf.page.width - 88, align: "center" }); } pdf.end(); }); }
function tablePage(pdf, name, rows, photos) { pdf.addPage(); pdf.fillColor("#003b73").font("Helvetica-Bold").fontSize(19).text(name); pdf.moveDown(); const list = Array.isArray(rows) ? rows : []; if (!list.length) pdf.font("Helvetica").fontSize(9).fillColor("#475569").text("Aucune mesure renseignée."); list.forEach(row => { pdf.rect(44, pdf.y, 507, 22).fill("#f1f5f9"); pdf.fillColor("#172033").font("Helvetica-Bold").fontSize(9).text(row.label || "Mesure", 52, pdf.y - 15, { width: 260 }); pdf.font("Helvetica").text(`${row.value || "—"} ${row.unit || ""}`, 330, pdf.y - 11, { width: 200, align: "right" }); pdf.moveDown(.8); }); addPhotos(pdf, photos, 3); }
function addPhotos(pdf, photos, maximum) { photos.slice(0, maximum).forEach(photo => { try { if (pdf.y > 650) pdf.addPage(); pdf.moveDown(.5); pdf.image(dataUrlBuffer(photo.dataUrl), 44, pdf.y, { fit: [500, 230] }); pdf.y += 238; pdf.fillColor("#475569").fontSize(8).text([photo.caption, photo.annotation].filter(Boolean).join(" · ") || photo.name, { width: 500 }); } catch {} }); }
function addSignature(pdf, dataUrl, label, y) { pdf.fillColor("#003b73").font("Helvetica-Bold").fontSize(10).text(label, 44, y); pdf.rect(44, y + 20, 220, 105).strokeColor("#cbd5e1").stroke(); if (dataUrl) { try { pdf.image(dataUrlBuffer(dataUrl), 52, y + 27, { fit: [205, 88] }); } catch {} } }
function dataUrlBuffer(value) { const match = /^data:[^;,]+;base64,([a-zA-Z0-9+/=]+)$/.exec(String(value || "")); if (!match) throw new Error("Média invalide"); return Buffer.from(match[1], "base64"); }
function sectionKey(name) { return ({ "État des lieux": "overview", "Description de l’installation": "installation", "Contrôle visuel": "visual", "Recherche de fuite": "leakSearch", "Localisation de la fuite": "location", "Travaux réalisés": "work", "Conclusion et préconisations": "conclusion" })[name] || ""; }
function formatDate(value) { return value ? new Intl.DateTimeFormat("fr-FR").format(new Date(`${value}T12:00:00`)) : ""; }
const CLIENT_ID = /^client-[a-zA-Z0-9-]+$/;
function validDate(value) { const date = String(value || ""); return /^\d{4}-\d{2}-\d{2}$/.test(date) && !Number.isNaN(new Date(`${date}T12:00:00`).getTime()) ? date : ""; }
function positiveId(value) { const id = Number(value); return Number.isSafeInteger(id) && id > 0 ? id : 0; }
function cleanText(value, max) { return String(value || "").replace(/\s+/g, " ").trim().slice(0, max); }
function safeName(value) { return path.basename(String(value || "photo")).replace(/[\r\n]/g, " ").slice(0, 255) || "photo"; }
export function technicalReportUploadErrorHandler(error, request, response, next) { if (error instanceof multer.MulterError) return response.status(400).json({ message: error.code === "LIMIT_FILE_SIZE" ? "Chaque photo est limitée à 4 Mo." : "Ajout des photos impossible." }); return next(error); }
function asyncHandler(handler) { return (request, response, next) => Promise.resolve(handler(request, response, next)).catch(next); }
